using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly Uri baseAddress;

    private string? receivedMethod;
    private string? receivedPath;
    private string? receivedContentType;
    private string? receivedBody;

    public HttpPaymentGatewayTests()
    {
        // Retry on the rare port collision between probing a free port and binding it.
        for (var attempt = 0; ; attempt++)
        {
            var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
            probe.Start();
            var port = ((IPEndPoint)probe.LocalEndpoint).Port;
            probe.Stop();
            try
            {
                listener.Prefixes.Clear();
                listener.Prefixes.Add($"http://127.0.0.1:{port}/");
                listener.Start();
                baseAddress = new Uri($"http://127.0.0.1:{port}");
                break;
            }
            catch (HttpListenerException) when (attempt < 5) { }
        }

        client = new HttpClient { BaseAddress = baseAddress };
    }

    [Fact]
    public async Task The_request_is_a_json_post_with_reference_amount_and_currency()
    {
        var served = Serve(200, """{"status":"approved"}""");

        await new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);
        await served;

        Assert.Equal("POST", receivedMethod);
        Assert.Equal("/v1/authorizations", receivedPath);
        Assert.StartsWith("application/json", receivedContentType);
        using var json = JsonDocument.Parse(receivedBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        var served = Serve(200, """{"status":"approved"}""");

        var outcome = await Authorize();
        await served;

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        var served = Serve(200, """{"status":"declined"}""");

        var outcome = await Authorize();
        await served;

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        var served = Serve(200, """{"id":"abc","status":"approved","score":0.3}""");

        var outcome = await Authorize();
        await served;

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task An_outright_refusal_with_402_is_a_decline()
    {
        var served = Serve(402, """{"error":"card_refused"}""");

        var outcome = await Authorize();
        await served;

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failure_statuses_are_errors_not_declines(int status)
    {
        var served = Serve(status, """{"error":"nope"}""");

        var error = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        await served;

        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    [Fact]
    public async Task An_answer_that_is_not_json_is_an_error()
    {
        var served = Serve(200, "<html>oops</html>");

        await Assert.ThrowsAnyAsync<JsonException>(Authorize);
        await served;
    }

    [Fact]
    public async Task An_unknown_status_is_never_treated_as_approved()
    {
        var served = Serve(200, """{"status":"pending"}""");

        var outcome = await Authorize();
        await served;

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_answer_without_a_status_is_never_treated_as_approved()
    {
        var served = Serve(200, """{"decision":"approved"}""");

        var outcome = await Authorize();
        await served;

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12, "EUR"), CancellationToken.None);

    private async Task Serve(int status, string body)
    {
        var context = await listener.GetContextAsync();
        receivedMethod = context.Request.HttpMethod;
        receivedPath = context.Request.Url!.AbsolutePath;
        receivedContentType = context.Request.ContentType;
        using (var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8))
            receivedBody = await reader.ReadToEndAsync();

        var bytes = Encoding.UTF8.GetBytes(body);
        context.Response.StatusCode = status;
        context.Response.ContentType = "application/json";
        await context.Response.OutputStream.WriteAsync(bytes);
        context.Response.Close();
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
